from src.nodes.base import BaseNode
from src.runtime.assets.semantic import (
    get_asset_storytelling_mapper, get_asset_query_engine,
    STORYTELLING_ROLES,
)

class Hou_Mcp_Asset_Storytelling(BaseNode):
    name = "hou_mcp_asset_storytelling"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",     "string", widget_type="text", default="map")
        self.add_input("asset_data", "any")
        self.add_input("story_role", "string", widget_type="text")
        self.add_input("limit",      "int",    widget_type="int", default=20)
        self.add_output("story_role",  "string")
        self.add_output("confidence",  "float")
        self.add_output("assets",      "list")
        self.add_output("result",      "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action     = str(inputs.get("action") or "map").strip().lower()
        asset_data = inputs.get("asset_data") or {}
        story_role = str(inputs.get("story_role") or "").strip()
        limit      = int(inputs.get("limit") or 20)
        try:
            if action == "map":
                mapping = get_asset_storytelling_mapper().map_story_role(
                    asset_data if isinstance(asset_data, dict) else {}
                )
                return {
                    "story_role": mapping.story_role,
                    "confidence": mapping.confidence,
                    "assets":     [],
                    "result":     mapping.to_dict(),
                    "exec_out":   True,
                }
            elif action == "query":
                result = get_asset_query_engine().query_storytelling(story_role, limit=limit)
                return {
                    "story_role": story_role,
                    "confidence": 1.0,
                    "assets":     result.assets,
                    "result":     result.to_dict(),
                    "exec_out":   True,
                }
            elif action == "list_roles":
                return {
                    "story_role": "",
                    "confidence": 0.0,
                    "assets":     [],
                    "result":     {"roles": sorted(STORYTELLING_ROLES)},
                    "exec_out":   True,
                }
            else:
                return {"story_role": "", "confidence": 0.0, "assets": [], "result": {}, "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_storytelling failed: {e}")
            return {"story_role": "", "confidence": 0.0, "assets": [], "result": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Storytelling
